name: PR Status Labeler

on:
  pull_request_target:
    types: [opened, synchronize, reopened, labeled, unlabeled]

jobs:
  capture-pr-data:
    if: github.event_name == 'pull_request_target'
    runs-on: ubuntu-latest
    permissions:
      contents: read
    outputs:
      pr-number: ${{ steps.set-outputs.outputs.pr-number }}
      pr-author: ${{ steps.set-outputs.outputs.pr-author }}
      pr-base: ${{ steps.set-outputs.outputs.pr-base }}
      pr-head: ${{ steps.set-outputs.outputs.pr-head }}
      pr-title: ${{ steps.set-outputs.outputs.pr-title }}
      pr-body: ${{ steps.set-outputs.outputs.pr-body }}
      pr-files: ${{ steps.set-outputs.outputs.pr-files }}
      pr-labels: ${{ steps.set-outputs.outputs.pr-labels }}
      pr-merged: ${{ steps.set-outputs.outputs.pr-merged }}
      pr-mergeable: ${{ steps.set-outputs.outputs.pr-mergeable }}
      pr-mergeable-state: ${{ steps.set-outputs.outputs.pr-mergeable-state }}
      pr-draft: ${{ steps.set-outputs.outputs.pr-draft }}
      pr-created-at: ${{ steps.set-outputs.outputs.pr-created-at }}
      pr-updated-at: ${{ steps.set-outputs.outputs.pr-updated-at }}
      pr-closed-at: ${{ steps.set-outputs.outputs.pr-closed-at }}
      pr-merged-at: ${{ steps.set-outputs.outputs.pr-merged-at }}
      pr-url: ${{ steps.set-outputs.outputs.pr-url }}
      pr-html-url: ${{ steps.set-outputs.outputs.pr-html-url }}
      pr-api-url: ${{ steps.set-outputs.outputs.pr-api-url }}
      pr-head-repo: ${{ steps.set-outputs.outputs.pr-head-repo }}
      pr-head-owner: ${{ steps.set-outputs.outputs.pr-head-owner }}
      pr-head-branch: ${{ steps.set-outputs.outputs.pr-head-branch }}
      pr-base-repo: ${{ steps.set-outputs.outputs.pr-base-repo }}
      pr-base-owner: ${{ steps.set-outputs.outputs.pr-base-owner }}
      pr-base-branch: ${{ steps.set-outputs.outputs.pr-base-branch }}
      pr-assignees: ${{ steps.set-outputs.outputs.pr-assignees }}
      pr-requested-reviewers: ${{ steps.set-outputs.outputs.pr-requested-reviewers }}
      pr-review-requests: ${{ steps.set-outputs.outputs.pr-review-requests }}
      pr-comments: ${{ steps.set-outputs.outputs.pr-comments }}
      pr-commits: ${{ steps.set-outputs.outputs.pr-commits }}
      pr-merge-commit-sha: ${{ steps.set-outputs.outputs.pr-merge-commit-sha }}
    steps:
      - name: Set outputs
        id: set-outputs
        run: |
          echo "pr-number=${{ github.event.number }}" >> $GITHUB_OUTPUT
          echo "pr-author=${{ github.event.pull_request.user.login }}" >> $GITHUB_OUTPUT
          echo "pr-base=${{ github.event.pull_request.base.sha }}" >> $GITHUB_OUTPUT
          echo "pr-head=${{ github.event.pull_request.head.sha }}" >> $GITHUB_OUTPUT
          echo "pr-title=${{ github.event.pull_request.title }}" >> $GITHUB_OUTPUT
          echo "pr-body=${{ github.event.pull_request.body }}" >> $GITHUB_OUTPUT
          echo "pr-files=0" >> $GITHUB_OUTPUT
          echo "pr-labels=0" >> $GITHUB_OUTPUT
          echo "pr-merged=${{ github.event.pull_request.merged }}" >> $GITHUB_OUTPUT
          echo "pr-mergeable=${{ github.event.pull_request.mergeable }}" >> $GITHUB_OUTPUT
          echo "pr-mergeable-state=${{ github.event.pull_request.mergeable_state }}" >> $GITHUB_OUTPUT
          echo "pr-draft=${{ github.event.pull_request.draft }}" >> $GITHUB_OUTPUT
          echo "pr-created-at=${{ github.event.pull_request.created_at }}" >> $GITHUB_OUTPUT
          echo "pr-updated-at=${{ github.event.pull_request.updated_at }}" >> $GITHUB_OUTPUT
          echo "pr-closed-at=${{ github.event.pull_request.closed_at }}" >> $GITHUB_OUTPUT
          echo "pr-merged-at=${{ github.event.pull_request.merged_at }}" >> $GITHUB_OUTPUT
          echo "pr-url=${{ github.event.pull_request.url }}" >> $GITHUB_OUTPUT
          echo "pr-html-url=${{ github.event.pull_request.html_url }}" >> $GITHUB_OUTPUT
          echo "pr-api-url=${{ github.event.pull_request._links.self.href }}" >> $GITHUB_OUTPUT
          echo "pr-head-repo=${{ github.event.pull_request.head.repo.full_name }}" >> $GITHUB_OUTPUT
          echo "pr-head-owner=${{ github.event.pull_request.head.repo.owner.login }}" >> $GITHUB_OUTPUT
          echo "pr-head-branch=${{ github.event.pull_request.head.ref }}" >> $GITHUB_OUTPUT
          echo "pr-base-repo=${{ github.event.pull_request.base.repo.full_name }}" >> $GITHUB_OUTPUT
          echo "pr-base-owner=${{ github.event.pull_request.base.repo.owner.login }}" >> $GITHUB_OUTPUT
          echo "pr-base-branch=${{ github.event.pull_request.base.ref }}" >> $GITHUB_OUTPUT
          echo "pr-assignees=0" >> $GITHUB_OUTPUT
          echo "pr-requested-reviewers=0" >> $GITHUB_OUTPUT
          echo "pr-review-requests=0" >> $GITHUB_OUTPUT
          echo "pr-comments=0" >> $GITHUB_OUTPUT
          echo "pr-commits=0" >> $GITHUB_OUTPUT
          echo "pr-merge-commit-sha=${{ github.event.pull_request.merge_commit_sha }}" >> $GITHUB_OUTPUT

  pr-status-labeler:
    needs: capture-pr-data
    if: github.event_name == 'pull_request_target'
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Label PR
        uses: actions/labeler@v5
        with:
          repo-token: "${{ secrets.GITHUB_TOKEN }}"
          configuration-path: .github/labeler.yml
          sync-labels: true
